/**
 * Kortet med byerne som links. $antal = antal billeder pr. by-id.
 * Uden $valgt (forsiden) vises alle bynavne. Med $valgt (by-siderne) vises kun den
 * valgte by med navn, og de andre byer er små prikker, man kan klikke på.
 */
function gronlandskort(array $byer, array $antal = [], ?int $valgt = null): string
{
    $viewbox = $valgt === null ? '40 22 320 478' : '0 0 400 535';
    $titel = $valgt === null ? 'Kort over Grønland – vælg en by' : 'Kort over Grønland – ' . h($byer[$valgt]['navn'] ?? '');
    $svg = '<svg class="gronlandskort' . ($valgt === null ? '' : ' bykort') . '" viewBox="' . $viewbox . '" role="img" aria-label="' . $titel . '">'
        . '<path class="land" d="' . GRONLAND_KYST . '"/>';
    if ($valgt === null) {
        $svg .= '<text class="landnavn" x="206" y="174" text-anchor="middle">Grønland</text>';
    }
    foreach ($byer as $by) {
        $denne = $by['id'] === $valgt;
        $med_navn = $valgt === null || $denne;
        $venstre = $by['side'] === 'v';
        $tekst_x = $venstre ? $by['x'] - 3 : $by['x'] + 11;
        $billeder = $antal[$by['id']] ?? 0;
        $svg .= '<a class="by' . ($denne ? ' valgt' : '') . ($med_navn ? '' : ' anden') . '" href="vis_billeder.php?byid=' . $by['id'] . '"' . ($denne ? ' aria-current="page"' : '') . '>'
            . '<title>' . h($by['navn']) . ' – ' . $billeder . ' billeder</title>'
            . '<rect class="prik" x="' . $by['x'] . '" y="' . ($by['y'] - 4) . '" width="8" height="8" rx="1.5"/>'
            . ($med_navn ? '<text x="' . $tekst_x . '" y="' . ($by['y'] + 4) . '"' . ($venstre ? ' text-anchor="end"' : '') . '>' . h($by['navn']) . '</text>' : '')
            . '</a>';
    }
    return $svg . '</svg>';
}
